import React, { useState } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { 
  LayoutDashboard, 
  FileText, 
  LogOut, 
  Shield,
  ArrowLeft,
  Menu,
  X,
  ChevronRight
} from 'lucide-react';

const Layout = ({ children, showBackButton = false, backButtonText = 'Back to Dashboard' }) => {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  const handleLogout = () => {
    logout();
    navigate('/login');
  };

  const navigation = [
    { name: 'Dashboard', href: '/', icon: LayoutDashboard },
    { name: 'Risk Register', href: '/risks', icon: FileText },
  ];

  const isActive = (href) => {
    return location.pathname === href || 
      (href !== '/' && location.pathname.startsWith(href));
  };

  return (
    <div style={{ display: 'flex', minHeight: '100vh', backgroundColor: '#f3f4f6' }}>
      {/* Desktop Sidebar */}
      <aside style={{ 
        width: '16rem', 
        backgroundColor: '#1f2937', 
        color: 'white',
        display: 'none',
        flexDirection: 'column',
        position: 'fixed',
        height: '100vh',
        zIndex: 50
      }} className="desktop-sidebar">
        <div style={{ padding: '1.5rem', borderBottom: '1px solid #374151' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
            <Shield size={28} style={{ color: '#60a5fa' }} />
            <div>
              <h1 style={{ fontSize: '1.125rem', fontWeight: 'bold' }}>Risk Management</h1>
              <p style={{ fontSize: '0.75rem', color: '#9ca3af' }}>Enterprise System</p>
            </div>
          </div>
        </div>

        <nav style={{ padding: '1rem', flex: 1 }}>
          {navigation.map((item) => (
            <button
              key={item.name}
              onClick={() => navigate(item.href)}
              style={{
                display: 'flex',
                alignItems: 'center',
                gap: '0.75rem',
                width: '100%',
                padding: '0.75rem 1rem',
                marginBottom: '0.5rem',
                backgroundColor: isActive(item.href) ? '#374151' : 'transparent',
                color: isActive(item.href) ? 'white' : '#d1d5db',
                border: 'none',
                borderRadius: '0.375rem',
                cursor: 'pointer',
                textAlign: 'left',
                fontSize: '0.875rem',
                fontWeight: '500',
                transition: 'all 0.2s',
              }}
              onMouseOver={(e) => {
                if (!isActive(item.href)) {
                  e.target.style.backgroundColor = '#374151';
                  e.target.style.color = 'white';
                }
              }}
              onMouseOut={(e) => {
                if (!isActive(item.href)) {
                  e.target.style.backgroundColor = 'transparent';
                  e.target.style.color = '#d1d5db';
                }
              }}
            >
              <item.icon size={20} />
              {item.name}
            </button>
          ))}
        </nav>

        <div style={{ padding: '1rem', borderTop: '1px solid #374151' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', marginBottom: '0.75rem' }}>
            <div style={{ 
              width: '2.5rem', 
              height: '2.5rem', 
              borderRadius: '50%', 
              backgroundColor: '#4b5563', 
              display: 'flex', 
              alignItems: 'center', 
              justifyContent: 'center', 
              fontWeight: 'bold',
              fontSize: '0.875rem'
            }}>
              {user?.full_name?.charAt(0) || user?.username?.charAt(0) || 'U'}
            </div>
            <div style={{ flex: 1, minWidth: 0 }}>
              <p style={{ fontSize: '0.875rem', fontWeight: '500', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                {user?.full_name || user?.username}
              </p>
              <p style={{ fontSize: '0.75rem', color: '#9ca3af', textTransform: 'capitalize' }}>
                {user?.role?.replace('_', ' ')}
              </p>
            </div>
          </div>
          <button
            onClick={handleLogout}
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: '0.75rem',
              width: '100%',
              padding: '0.5rem 1rem',
              backgroundColor: 'transparent',
              color: '#f87171',
              border: '1px solid #374151',
              borderRadius: '0.375rem',
              cursor: 'pointer',
              fontSize: '0.875rem',
              transition: 'all 0.2s',
            }}
            onMouseOver={(e) => e.target.style.backgroundColor = '#374151'}
            onMouseOut={(e) => e.target.style.backgroundColor = 'transparent'}
          >
            <LogOut size={18} />
            Sign Out
          </button>
        </div>
      </aside>

      {/* Mobile Header */}
      <header style={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        padding: '0.75rem 1rem',
        backgroundColor: '#1f2937',
        color: 'white',
        position: 'fixed',
        top: 0,
        left: 0,
        right: 0,
        zIndex: 40
      }} className="mobile-header">
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
          <Shield size={24} style={{ color: '#60a5fa' }} />
          <span style={{ fontSize: '1rem', fontWeight: 'bold' }}>Risk Management</span>
        </div>
        <button
          onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
          style={{
            background: 'none',
            border: 'none',
            color: 'white',
            cursor: 'pointer',
            padding: '0.5rem'
          }}
        >
          {mobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
        </button>
      </header>

      {/* Mobile Menu */}
      {mobileMenuOpen && (
        <div style={{
          position: 'fixed',
          top: '3.5rem',
          left: 0,
          right: 0,
          bottom: 0,
          backgroundColor: '#1f2937',
          zIndex: 30,
          padding: '1rem',
          overflow: 'auto'
        }} className="mobile-menu">
          <div style={{ display: 'flex', flexDirection: 'column', height: 'calc(100% - 100px)' }}>
            <nav style={{ flex: 1 }}>
              {navigation.map((item) => (
                <button
                  key={item.name}
                  onClick={() => {
                    navigate(item.href);
                    setMobileMenuOpen(false);
                  }}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: '0.75rem',
                    width: '100%',
                    padding: '1rem',
                    marginBottom: '0.5rem',
                    backgroundColor: isActive(item.href) ? '#374151' : 'transparent',
                    color: isActive(item.href) ? 'white' : '#d1d5db',
                    border: 'none',
                    borderRadius: '0.5rem',
                    cursor: 'pointer',
                    textAlign: 'left',
                    fontSize: '1rem',
                    fontWeight: '500',
                  }}
                >
                  <item.icon size={22} />
                  {item.name}
                </button>
              ))}
            </nav>

            <div style={{ 
              padding: '1rem', 
              backgroundColor: '#374151', 
              borderRadius: '0.5rem',
              marginBottom: '1rem'
            }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', marginBottom: '0.75rem' }}>
                <div style={{ 
                  width: '3rem', 
                  height: '3rem', 
                  borderRadius: '50%', 
                  backgroundColor: '#4b5563', 
                  display: 'flex', 
                  alignItems: 'center', 
                  justifyContent: 'center', 
                  fontWeight: 'bold',
                  fontSize: '1.125rem'
                }}>
                  {user?.full_name?.charAt(0) || user?.username?.charAt(0) || 'U'}
                </div>
                <div>
                  <p style={{ fontSize: '1rem', fontWeight: '500' }}>
                    {user?.full_name || user?.username}
                  </p>
                  <p style={{ fontSize: '0.875rem', color: '#9ca3af', textTransform: 'capitalize' }}>
                    {user?.role?.replace('_', ' ')}
                  </p>
                </div>
              </div>
              <button
                onClick={handleLogout}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: '0.75rem',
                  width: '100%',
                  padding: '0.75rem 1rem',
                  backgroundColor: 'transparent',
                  color: '#f87171',
                  border: '1px solid #6b7280',
                  borderRadius: '0.375rem',
                  cursor: 'pointer',
                  fontSize: '1rem',
                }}
              >
                <LogOut size={20} />
                Sign Out
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Main Content */}
      <main style={{ 
        flex: 1, 
        overflow: 'auto',
        marginLeft: 0,
        marginTop: '3.5rem',
        minHeight: 'calc(100vh - 3.5rem)'
      }} className="main-content">
        {/* Desktop Back Button */}
        {showBackButton && (
          <div style={{ 
            display: 'none',
            padding: '1rem 1.5rem',
            backgroundColor: 'white',
            borderBottom: '1px solid #e5e7eb'
          }} className="back-button-container">
            <button
              onClick={() => navigate('/')}
              style={{
                display: 'flex',
                alignItems: 'center',
                gap: '0.5rem',
                padding: '0.5rem 1rem',
                backgroundColor: '#f3f4f6',
                color: '#374151',
                border: '1px solid #d1d5db',
                borderRadius: '0.375rem',
                cursor: 'pointer',
                fontSize: '0.875rem',
                fontWeight: '500',
                transition: 'all 0.2s',
              }}
              onMouseOver={(e) => {
                e.target.style.backgroundColor = '#e5e7eb';
                e.target.style.borderColor = '#9ca3af';
              }}
              onMouseOut={(e) => {
                e.target.style.backgroundColor = '#f3f4f6';
                e.target.style.borderColor = '#d1d5db';
              }}
            >
              <ArrowLeft size={18} />
              {backButtonText}
            </button>
          </div>
        )}

        {/* Mobile Back Button */}
        {showBackButton && (
          <div style={{
            display: 'flex',
            padding: '0.75rem 1rem',
            backgroundColor: 'white',
            borderBottom: '1px solid #e5e7eb',
            alignItems: 'center',
            gap: '0.75rem'
          }} className="mobile-back-button">
            <button
              onClick={() => navigate('/')}
              style={{
                display: 'flex',
                alignItems: 'center',
                gap: '0.5rem',
                padding: '0.5rem 0.75rem',
                backgroundColor: '#f3f4f6',
                color: '#374151',
                border: '1px solid #d1d5db',
                borderRadius: '0.375rem',
                cursor: 'pointer',
                fontSize: '0.875rem',
                fontWeight: '500',
              }}
            >
              <ArrowLeft size={16} />
              Back
            </button>
            <span style={{ fontSize: '0.875rem', color: '#6b7280' }}>
              {backButtonText}
            </span>
          </div>
        )}

        {children}
      </main>

      <style>{`
        @media (min-width: 768px) {
          .desktop-sidebar {
            display: flex !important;
          }
          .mobile-header {
            display: none !important;
          }
          .mobile-menu {
            display: none !important;
          }
          .main-content {
            margin-left: 16rem !important;
            margin-top: 0 !important;
          }
          .back-button-container {
            display: block !important;
          }
          .mobile-back-button {
            display: none !important;
          }
        }

        @media (max-width: 767px) {
          .desktop-sidebar {
            display: none !important;
          }
          .main-content {
            margin-top: 3.5rem !important;
            margin-left: 0 !important;
          }
        }
      `}</style>
    </div>
  );
};

export default Layout;
